1	<!doctype html>
2	<html lang="vi">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width,initial-scale=1">
6	<title>Prototype · Giờ và thời tiết thực tế tại Đà Nẵng</title>
7	<!-- PROTOTYPE THIẾT KẾ ĐỘC LẬP. Không thuộc ứng dụng, không được Vite build, không gọi API thời tiết: số liệu là dữ liệu giả.
8	     Nền là ảnh chụp cảnh 3D thật (img/), các bảng ⚙ / ☰ / Thông số / FPS là bản dựng lại để xem độ hài hoà. Đồng hồ chạy thật theo Asia/Ho_Chi_Minh. -->
9	<link rel="preconnect" href="https://fonts.googleapis.com">
10	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
11	<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@500;600;700&family=Be+Vietnam+Pro:wght@400;500;600&family=JetBrains+Mono:wght@400;500&display=swap">
12	<style>
13	/* ===== Biến của ứng dụng thật (chép từ src/styles/main.css) ===== */
14	:root{
15	  --ink:#0b1216;--panel:rgba(10,18,22,.78);--panel-line:rgba(226,186,104,.26);
16	  --gold:#e6bd6a;--gold-deep:#a97a28;--text:#eef0ea;--muted:#9fb0ad;--han:#5aa89a;
17	  --font-display:'Cormorant Garamond','Times New Roman',serif;
18	  --font-body:'Be Vietnam Pro',system-ui,-apple-system,'Segoe UI',sans-serif;
19	  --font-mono:'JetBrains Mono',ui-monospace,Menlo,Consolas,monospace;
20	  color-scheme:dark;
21	}
22	*{box-sizing:border-box;}
23	[hidden]{display:none!important;}
24	html,body{margin:0;min-height:100%;background:#070b0e;color:var(--text);font-family:var(--font-body);}
25	
26	/* ===== Thanh điều khiển của trang duyệt (không thuộc thiết kế) ===== */
27	.review{display:flex;flex-wrap:wrap;gap:10px 22px;align-items:flex-end;padding:14px 20px 12px;border-bottom:1px solid rgba(255,255,255,.07);}
28	.review h1{flex:1 0 100%;margin:0 0 2px;font:600 15px/1.3 var(--font-body);color:var(--text);}
29	.review h1 small{font-weight:400;color:var(--muted);font-size:12px;margin-inline-start:8px;}
30	.ctl{display:flex;flex-direction:column;gap:5px;}
31	.ctl > span{font:500 10px/1 var(--font-mono);letter-spacing:.12em;text-transform:uppercase;color:var(--muted);}
32	.segc{display:flex;gap:2px;padding:2px;border:1px solid rgba(255,255,255,.1);border-radius:7px;background:rgba(255,255,255,.03);}
33	.segc button{font:500 12px/1 var(--font-body);color:var(--muted);background:transparent;border:0;border-radius:5px;padding:7px 10px;cursor:pointer;white-space:nowrap;}
34	.segc button:hover{color:var(--text);}
35	.segc button[aria-pressed="true"]{background:rgba(230,189,106,.18);color:var(--gold);}
36	.segc button:focus-visible{outline:2px solid var(--gold);outline-offset:1px;}
37	.caption{padding:10px 20px 0;font-size:12.5px;line-height:1.55;color:var(--muted);max-width:110ch;}
38	.caption b{color:var(--text);font-weight:500;}
39	
40	/* ===== Khung mô phỏng ứng dụng ===== */
41	.stage{padding:14px 20px 28px;display:flex;justify-content:center;}
42	.app{position:relative;width:100%;max-width:1600px;aspect-ratio:16/9;min-height:560px;overflow:hidden;border-radius:10px;background:#0b1216;box-shadow:0 0 0 1px rgba(255,255,255,.08),0 30px 80px rgba(0,0,0,.5);isolation:isolate;}
43	.app.compact{width:390px;max-width:none;aspect-ratio:auto;height:780px;min-height:0;border-radius:40px;box-shadow:0 0 0 9px #161c20,0 0 0 10px rgba(255,255,255,.1),0 30px 80px rgba(0,0,0,.6);}
44	.scene{position:absolute;inset:0;z-index:0;}
45	.scene img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:0;transition:opacity .7s;}
46	.scene img.on{opacity:1;}
47	
48	/* --- Các bảng có sẵn của ứng dụng, dựng lại để so --- */
49	.panel{position:absolute;background:var(--panel);border:1px solid var(--panel-line);border-radius:6px;backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);box-shadow:0 10px 30px rgba(0,0,0,.35);z-index:2;}
50	.app button.ui{font:500 12.5px/1.2 var(--font-body);color:var(--text);background:rgba(255,255,255,.04);border:1px solid rgba(230,189,106,.32);border-radius:4px;padding:8px 11px;cursor:pointer;transition:background .15s,border-color .15s,color .15s;}
51	.app button.ui:hover{background:rgba(230,189,106,.12);}
52	.app button.ui[aria-pressed="true"]{background:linear-gradient(180deg,var(--gold),var(--gold-deep));color:#1a1206;border-color:var(--gold);}
53	.brand{top:14px;left:14px;padding:6px;display:flex;flex-direction:column;gap:10px;max-width:340px;}
54	.brand .head{display:flex;align-items:center;gap:10px;}
55	.brand h2{display:none;margin:0;font:600 34px/1 var(--font-display);color:var(--gold);}
56	.brand .body{display:none;flex-direction:column;gap:10px;}
57	#btnSettings{display:inline-flex;align-items:center;justify-content:center;width:36px;height:36px;padding:0;flex:none;}
58	#btnSettings svg{width:16px;height:16px;}
59	.app.sheet-settings .brand{padding:14px 16px;}
60	.app.sheet-settings .brand h2{display:block;}
61	.app.sheet-settings .brand .body{display:flex;}
62	.app.sheet-settings #btnSettings{background:rgba(230,189,106,.16);border-color:rgba(230,189,106,.55);color:var(--gold);}
63	.eyebrow{font:400 10.5px/1.3 var(--font-mono);letter-spacing:.14em;text-transform:uppercase;color:var(--han);}
64	.rowx{display:flex;flex-wrap:wrap;gap:6px;}
65	.sliderx{display:flex;align-items:center;gap:8px;font-size:11.5px;color:var(--muted);}
66	.sliderx input{flex:1;accent-color:var(--gold);min-width:0;}
67	.minisel{display:flex;flex-direction:column;gap:4px;font-size:10.5px;color:var(--muted);}
68	.minisel select{font:500 12px/1.2 var(--font-body);color:var(--text);background:rgba(255,255,255,.04);border:1px solid rgba(230,189,106,.32);border-radius:4px;padding:6px;}
69	.minisel select option{background:var(--ink);}
70	.viewsbtn{top:14px;right:14px;padding:6px;}
71	.viewsbtn .ui{display:inline-flex;align-items:center;gap:6px;padding:8px 12px;height:36px;}
72	.viewsbtn svg{width:14px;height:14px;}
73	.specs{left:14px;bottom:14px;padding:12px 16px;}
74	.specs .label{font:400 10px/1.3 var(--font-mono);letter-spacing:.14em;text-transform:uppercase;color:var(--muted);margin-bottom:2px;}
75	.specs dl{margin:0;display:grid;grid-template-columns:repeat(4,auto);gap:4px 22px;}
76	.specs dt{font-size:10.5px;color:var(--muted);}
77	.specs dd{margin:0;font:600 22px/1.2 var(--font-display);color:var(--gold);}
78	.specs small{display:block;margin-top:6px;font-size:10.5px;color:var(--muted);max-width:44ch;line-height:1.4;}
79	.stats{right:14px;bottom:14px;padding:10px 14px;font:400 11.5px/1.6 var(--font-mono);color:var(--muted);min-width:180px;}
80	.stats b{color:var(--text);font-weight:500;}
81	/* Điện thoại (body.compact của ứng dụng): thanh trên + thanh dưới, không blur, ẩn Thông số / FPS */
82	.app.compact .panel{backdrop-filter:none;-webkit-backdrop-filter:none;box-shadow:none;background:rgba(10,18,22,.92);}
83	.app.compact .specs,.app.compact .stats,.app.compact .viewsbtn{display:none;}
84	.app.compact .brand{top:8px;left:8px;padding:6px 6px 6px 12px;}
85	.app.compact .brand h2{display:block;font-size:20px;line-height:1.15;}
86	.app.compact #btnSettings{width:40px;height:40px;}
87	.app.compact.sheet-settings .brand{top:auto;bottom:0;left:0;right:0;max-width:none;border-radius:14px 14px 0 0;padding:12px 14px 22px;z-index:6;}
88	.bar{display:none;}
89	.app.compact .bar{display:flex;left:0;right:0;bottom:0;border-radius:14px 14px 0 0;border-bottom:0;padding:8px 8px 18px;gap:6px;align-items:center;}
90	.bar .chips{display:flex;gap:3px;padding:3px;border:1px solid var(--panel-line);border-radius:5px;flex:1 1 0;min-width:0;overflow:hidden;-webkit-mask-image:linear-gradient(to right,#000 calc(100% - 28px),transparent);mask-image:linear-gradient(to right,#000 calc(100% - 28px),transparent);}
91	.bar .chips span{flex:none;padding:10px;font-size:13px;color:var(--muted);border-radius:4px;border:1px solid transparent;white-space:nowrap;}
92	.bar .chips span.on{background:rgba(230,189,106,.16);border-color:rgba(230,189,106,.55);color:var(--gold);}
93	.bar .ui{min-height:40px;font-size:13px;white-space:nowrap;display:inline-flex;align-items:center;gap:6px;}
94	.bar svg{width:16px;height:16px;}
95	
96	/* =====================================================================
97	   THIẾT KẾ MỚI: khối "Thực tế tại Đà Nẵng" (#env)
98	   Kính tối: nền trong, blur lớn, viền sáng mảnh, một quầng màu theo buổi thật (--acc).
99	   Giữ bộ chữ của ứng dụng: số lớn Cormorant Garamond, nhãn JetBrains Mono, chữ Be Vietnam Pro.
100	   ===================================================================== */
101	#env{--acc:140,200,240;--tint:10,18,24;--glass:.56;position:absolute;z-index:3;top:14px;left:72px;font-family:var(--font-body);color:var(--text);}
102	#env[data-phase="dawn"]{--acc:244,178,138;--tint:22,16,20;}
103	#env[data-phase="day"]{--acc:140,200,240;--tint:9,19,27;}
104	#env[data-phase="dusk"]{--acc:242,150,86;--tint:24,15,13;}
105	#env[data-phase="night"]{--acc:138,164,236;--tint:7,11,26;--glass:.62;}
106	.glass{
107	  background:
108	    radial-gradient(130% 90% at 100% 0%,rgba(var(--acc),.20),transparent 62%),
109	    linear-gradient(165deg,rgba(var(--tint),calc(var(--glass) + .1)),rgba(var(--tint),var(--glass)));
110	  border:1px solid rgba(255,255,255,.11);
111	  backdrop-filter:blur(22px) saturate(150%);-webkit-backdrop-filter:blur(22px) saturate(150%);
112	  box-shadow:0 18px 48px rgba(0,0,0,.34),0 2px 6px rgba(0,0,0,.2),inset 0 1px 0 rgba(255,255,255,.12);
113	  transition:background .9s,border-color .25s,box-shadow .25s,transform .25s;
114	}
115	.env-ico{width:1em;height:1em;flex:none;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round;color:rgb(var(--acc));transition:color .9s;}
116	
117	/* --- Chỉ báo gọn (phương án B, luôn hiện) --- */
118	.env-pill{display:none;align-items:center;gap:9px;height:44px;margin-top:3px;padding:0 14px 0 12px;border-radius:12px;color:var(--text);cursor:pointer;font:inherit;-webkit-tap-highlight-color:transparent;}
119	#env[data-concept="B"] .env-pill{display:inline-flex;}
120	.env-pill .env-ico{font-size:20px;}
121	.env-pill .t{font:600 23px/1 var(--font-display);color:var(--gold);font-variant-numeric:lining-nums tabular-nums;letter-spacing:.01em;}
122	.env-pill .sep{width:1px;height:16px;background:rgba(255,255,255,.16);}
123	.env-pill .hm{font:500 13.5px/1 var(--font-body);font-variant-numeric:tabular-nums;letter-spacing:.02em;}
124	.env-pill .ss{font:400 10.5px/1 var(--font-mono);color:var(--muted);opacity:.75;margin-inline-start:-5px;font-variant-numeric:tabular-nums;}
125	.env-pill .d{max-width:0;overflow:hidden;white-space:nowrap;font-size:12px;color:var(--muted);opacity:0;transition:max-width .35s cubic-bezier(.2,.7,.2,1),opacity .25s,margin .35s;margin-inline-start:-9px;}
126	.env-pill .chev{width:10px;height:10px;stroke:var(--muted);fill:none;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round;transition:transform .3s;}
127	@media (hover:hover){
128	  .env-pill:hover{border-color:rgba(255,255,255,.22);box-shadow:0 20px 50px rgba(0,0,0,.38),0 0 0 4px rgba(var(--acc),.08),inset 0 1px 0 rgba(255,255,255,.16);transform:translateY(-1px);}
129	  .env-pill:hover .d{max-width:180px;opacity:1;margin-inline-start:0;}
130	}
131	.env-pill:active{transform:translateY(0) scale(.985);}
132	.env-pill:focus-visible,.env-more:focus-visible,.env-x:focus-visible{outline:2px solid var(--gold);outline-offset:2px;}
133	#env.open .env-pill{border-color:rgba(var(--acc),.38);}
134	#env.open .env-pill .chev{transform:rotate(180deg);}
135	
136	/* --- Thẻ chi tiết (B: mở khi bấm; A: luôn hiện bản vừa, bấm "Chi tiết" để mở hết) --- */
137	.env-card{width:312px;border-radius:16px;padding:16px 18px 14px;display:flex;flex-direction:column;}
138	#env[data-concept="B"] .env-card{position:absolute;top:56px;left:0;transform-origin:20px 0;opacity:0;visibility:hidden;transform:translateY(-8px) scale(.975);transition:opacity .22s,transform .28s cubic-bezier(.2,.8,.2,1),visibility 0s .28s,background .9s;}
139	#env[data-concept="B"].open .env-card{opacity:1;visibility:visible;transform:none;transition:opacity .22s,transform .28s cubic-bezier(.2,.8,.2,1),visibility 0s,background .9s;}
140	.env-eyebrow{display:flex;align-items:center;gap:8px;font:400 10px/1.2 var(--font-mono);letter-spacing:.13em;text-transform:uppercase;color:var(--muted);}
141	.env-eyebrow .place{color:rgb(var(--acc));transition:color .9s;}
142	.env-eyebrow .tz{margin-inline-start:auto;letter-spacing:.08em;}
143	.live{position:relative;width:6px;height:6px;border-radius:50%;background:#7bd18b;flex:none;}
144	.live::after{content:"";position:absolute;inset:-4px;border-radius:50%;border:1px solid #7bd18b;opacity:.35;}
145	#env[data-state="stale"] .live{background:#e6bd6a;}#env[data-state="stale"] .live::after{border-color:#e6bd6a;}
146	#env[data-state="offline"] .live{background:#f07b6b;}#env[data-state="offline"] .live::after{border-color:#f07b6b;}
147	#env[data-state="loading"] .live{background:var(--muted);}#env[data-state="loading"] .live::after{border-color:var(--muted);}
148	.env-clock{display:flex;align-items:baseline;gap:6px;margin-top:10px;}
149	.env-clock .hm{font:500 52px/.92 var(--font-display);letter-spacing:.005em;font-variant-numeric:lining-nums tabular-nums;}
150	.env-clock .ss{font:400 13px/1 var(--font-mono);color:var(--muted);opacity:.7;font-variant-numeric:tabular-nums;}
151	.env-date{margin-top:7px;font-size:12.5px;color:var(--text);opacity:.86;}
152	.env-date::first-letter{text-transform:uppercase;}
153	/* Vạch mặt trời: mọc → lặn, chấm là vị trí hiện tại (cần daily=sunrise,sunset của Open-Meteo) */
154	.env-sun{margin-top:14px;}
155	.env-sun .track{position:relative;height:1px;background:linear-gradient(90deg,rgba(255,255,255,.08),rgba(var(--acc),.55),rgba(255,255,255,.08));}
156	.env-sun .dot{position:absolute;top:50%;width:7px;height:7px;margin:-3.5px 0 0 -3.5px;border-radius:50%;background:rgb(var(--acc));box-shadow:0 0 0 3px rgba(var(--acc),.18),0 0 12px rgba(var(--acc),.8);transition:left .8s cubic-bezier(.2,.7,.2,1),opacity .4s,background .9s;}
157	.env-sun .ends{display:flex;justify-content:space-between;margin-top:6px;font:400 10px/1 var(--font-mono);color:var(--muted);letter-spacing:.04em;}
158	.env-rule{height:1px;margin:14px 0 13px;background:linear-gradient(90deg,rgba(255,255,255,.12),rgba(255,255,255,.03));}
159	.env-now{display:flex;align-items:center;gap:14px;}
160	.env-now .env-ico{font-size:40px;stroke-width:1.25;}
161	.env-now .temp{font:600 64px/.82 var(--font-display);color:var(--gold);font-variant-numeric:lining-nums;letter-spacing:-.01em;min-width:1.55ch;}
162	.env-now .temp sup{font-size:.5em;vertical-align:top;line-height:1;margin-inline-start:1px;color:rgba(230,189,106,.8);}
163	.env-now .desc{display:flex;flex-direction:column;gap:4px;min-width:0;}
164	.env-now .desc b{font-weight:500;font-size:14px;line-height:1.25;}
165	.env-now .desc span{font-size:11.5px;color:var(--muted);}
166	.env-grid{margin:14px 0 0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px 10px;}
167	.env-grid div{display:flex;flex-direction:column;gap:3px;min-width:0;}
168	.env-grid dt{display:flex;align-items:center;gap:5px;font-size:10.5px;color:var(--muted);white-space:nowrap;}
169	.env-grid dt .env-ico{font-size:13px;opacity:.9;}
170	.env-grid dd{margin:0;font-size:13.5px;font-weight:500;font-variant-numeric:tabular-nums;white-space:nowrap;}
171	.env-grid dd small{font-size:10.5px;font-weight:400;color:var(--muted);margin-inline-start:3px;}
172	.env-grid .arrow{display:inline-block;width:11px;height:11px;margin-inline-end:4px;vertical-align:-1px;transition:transform .8s cubic-bezier(.2,.7,.2,1);}
173	.env-foot{margin-top:14px;padding-top:10px;border-top:1px solid rgba(255,255,255,.07);display:flex;justify-content:space-between;gap:10px;font-size:10.5px;line-height:1.45;color:var(--muted);}
174	.env-foot a{color:inherit;text-decoration:underline;text-underline-offset:2px;white-space:nowrap;}
175	.env-foot .warn{color:var(--gold);}
176	.env-x{display:none;}
177	.env-swap{transition:opacity .2s;}.env-swap.out{opacity:0;}
178	/* Đang tải: khối xám chạy sáng thay số; ngoại tuyến: số liệu mờ, đồng hồ vẫn chạy */
179	@keyframes sk{to{background-position:-200% 0;}}
180	#env[data-state="loading"] .v{color:transparent!important;border-radius:4px;background:linear-gradient(90deg,rgba(255,255,255,.07) 25%,rgba(255,255,255,.16) 50%,rgba(255,255,255,.07) 75%) 0 0/200% 100%;animation:sk 1.3s linear infinite;}
181	#env[data-state="loading"] .v *{visibility:hidden;}
182	#env[data-state="loading"] .env-now .env-ico,#env[data-state="loading"] .env-pill > .env-ico{opacity:.25;}
183	#env[data-state="stale"] .env-now,#env[data-state="stale"] .env-grid{opacity:.72;}
184	#env[data-state="offline"] .env-now .temp,#env[data-state="offline"] .env-pill .t{color:var(--muted);}
185	#env[data-state="offline"] .env-grid{opacity:.45;}
186	#env[data-state="offline"] .env-now .temp sup{display:none;}
187	#env[data-state="offline"] .env-now .temp{font-size:44px;line-height:1;letter-spacing:.02em;white-space:nowrap;}
188	
189	/* --- Phương án A: thẻ nổi luôn hiện, bản vừa; phần .more gập lại --- */
190	.env-more{display:none;}
191	.more{display:grid;grid-template-rows:1fr;transition:grid-template-rows .32s cubic-bezier(.2,.8,.2,1),opacity .25s;}
192	.more > div{overflow:hidden;min-height:0;}
193	#env[data-concept="A"]{top:14px;left:72px;}
194	#env[data-concept="A"] .env-card{width:264px;padding:13px 15px 8px;border-radius:14px;transition:width .32s cubic-bezier(.2,.8,.2,1),padding .32s,background .9s;}
195	#env[data-concept="A"]:not(.open) .more{grid-template-rows:0fr;opacity:0;}
196	#env[data-concept="A"]:not(.open) .env-clock .hm{font-size:36px;}
197	#env[data-concept="A"]:not(.open) .env-clock{margin-top:8px;}
198	#env[data-concept="A"]:not(.open) .env-rule{margin:10px 0;}
199	#env[data-concept="A"]:not(.open) .env-now .temp{font-size:46px;}
200	#env[data-concept="A"]:not(.open) .env-now .env-ico{font-size:30px;}
201	#env[data-concept="A"]:not(.open) .env-now{gap:10px;}
202	#env[data-concept="A"]:not(.open) .env-grid div:nth-child(n+4){display:none;}
203	#env[data-concept="A"].open .env-card{width:312px;padding:16px 18px 8px;}
204	#env[data-concept="A"] .env-more{display:flex;align-items:center;justify-content:center;gap:6px;margin-top:8px;padding:7px;border:0;border-top:1px solid rgba(255,255,255,.07);background:none;color:var(--muted);font:500 11px/1 var(--font-body);cursor:pointer;border-radius:0 0 8px 8px;transition:color .15s;}
205	#env[data-concept="A"] .env-more:hover{color:var(--text);}
206	#env[data-concept="A"] .env-more svg{width:10px;height:10px;stroke:currentColor;fill:none;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round;transition:transform .3s;}
207	#env[data-concept="A"].open .env-more svg{transform:rotate(180deg);}
208	.env-clock .hm,.env-now .temp,.env-now .env-ico{transition:font-size .32s cubic-bezier(.2,.8,.2,1),color .9s;}
209	
