323	<script>
324	/* ===== Dữ liệu giả, cùng hình dạng với current= của Open-Meteo (nhiệt độ °C, gió km/h, mưa mm) ===== */
325	const WX = {
326	  sunny:  { temp: 29, feels: 33, desc: 'Nắng, ít mây', descNight: 'Trời quang', ico: 'clear',  hum: 68, wind: 14, dir: 45,  rain: 0,   cloud: 18,  uv: 8 },
327	  cloudy: { temp: 26, feels: 29, desc: 'Nhiều mây',    descNight: 'Nhiều mây',  ico: 'cloudy', hum: 79, wind: 19, dir: 70,  rain: 0,   cloud: 86,  uv: 3 },
328	  rain:   { temp: 24, feels: 26, desc: 'Mưa vừa',      descNight: 'Mưa vừa',    ico: 'rain',   hum: 93, wind: 26, dir: 10,  rain: 3.4, cloud: 100, uv: 1 },
329	  night:  { temp: 25, feels: 27, desc: 'Nắng, ít mây', descNight: 'Trời quang', ico: 'clear',  hum: 84, wind: 9,  dir: 220, rain: 0,   cloud: 8,   uv: 0 },
330	};
331	const PRESET = { sunny: { time: 'day', scene: 'day' }, cloudy: { time: 'dusk', scene: 'dusk' }, rain: { time: 'dawn', scene: 'rain' }, night: { time: 'night', scene: 'night' } };
332	const TIME = { dawn: 5 * 60 + 48, day: 13 * 60 + 20, dusk: 17 * 60 + 2, night: 21 * 60 + 10 };   // phút trong ngày, giờ Đà Nẵng
333	const SUNRISE = 5 * 60 + 38, SUNSET = 17 * 60 + 17;   // giữa tháng 11 (bản thật lấy từ daily=sunrise,sunset)
334	const ICO = {
335	  'clear-d': '<circle cx="12" cy="12" r="4"/><path d="M12 2.8v2.4M12 18.8v2.4M2.8 12h2.4M18.8 12h2.4M5.5 5.5l1.7 1.7M16.8 16.8l1.7 1.7M5.5 18.5l1.7-1.7M16.8 7.2l1.7-1.7"/>',
336	  'clear-n': '<path d="M19.5 14.2A8 8 0 0 1 9.8 4.5a8 8 0 1 0 9.7 9.7z"/><path d="M17 4.2v2.6M15.7 5.5h2.6"/>',
337	  'cloudy-d': '<path d="M8.2 6.2l-.9-1.5M12.5 5V3.2M16 6.5l1.2-1.3M9 10.2a4 4 0 0 1 7.3-.6"/><path d="M7 19.5h10a3.6 3.6 0 0 0 .5-7.16A5 5 0 0 0 7.9 11.6 4 4 0 0 0 7 19.5z"/>',
338	  'cloudy-n': '<path d="M18.8 8.4a4.6 4.6 0 0 1-5.4-5.6 4.6 4.6 0 0 0-2.2 6.3"/><path d="M7 19.5h10a3.6 3.6 0 0 0 .5-7.16A5 5 0 0 0 7.9 11.6 4 4 0 0 0 7 19.5z"/>',
339	  'rain-d': '<path d="M7 15.5h10a3.8 3.8 0 0 0 .5-7.56A5.2 5.2 0 0 0 7.6 7.3 4.2 4.2 0 0 0 7 15.5z"/><path d="M8.5 18.2l-.9 2.4M12.4 18.2l-.9 2.4M16.3 18.2l-.9 2.4"/>',
340	};
341	ICO['rain-n'] = ICO['rain-d'];
342	const DIRS = ['Bắc', 'Đông Bắc', 'Đông', 'Đông Nam', 'Nam', 'Tây Nam', 'Tây', 'Tây Bắc'];
343	const UV = (v) => v <= 0 ? '' : v < 3 ? 'Thấp' : v < 6 ? 'Vừa' : v < 8 ? 'Cao' : v < 11 ? 'Rất cao' : 'Cực cao';
344	const vi = (n, d = 0) => n.toLocaleString('vi-VN', { minimumFractionDigits: d, maximumFractionDigits: d });
345	
346	/* ===== Trạng thái prototype (đọc / ghi qua ?c=B&wx=rain&time=dusk&scene=night&dev=mobile&data=stale&open=1) ===== */
347	const q = new URLSearchParams(location.search);
348	const S = { c: q.get('c') || 'B', wx: q.get('wx') || 'sunny', time: q.get('time') || 'live', scene: q.get('scene') || 'day', dev: q.get('dev') || 'desk', data: q.get('data') || 'ok', open: q.get('open') === '1', settings: q.get('settings') === '1' };
349	let offset = 0;   // ms cộng vào giờ thật khi chọn một buổi cố định
350	const app = document.getElementById('app'), env = document.getElementById('env');
351	const $$ = (sel) => [...env.querySelectorAll(sel)];
352	const set = (sel, text) => $$(sel).forEach((e) => { e.textContent = text; });
353	
354	/* ===== Đồng hồ: Intl với timeZone 'Asia/Ho_Chi_Minh', không phụ thuộc múi giờ của máy ===== */
355	const TZ = 'Asia/Ho_Chi_Minh';
356	const fTime = new Intl.DateTimeFormat('en-GB', { timeZone: TZ, hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23' });
357	const fDate = new Intl.DateTimeFormat('vi-VN', { timeZone: TZ, weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
358	const now = () => new Date(Date.now() + offset);
359	const minutes = (d) => { const [h, m] = fTime.format(d).split(':').map(Number); return h * 60 + m; };
360	const hhmm = (m) => `${String(Math.floor(m / 60)).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`;
361	function phaseOf(m) { return m >= SUNRISE - 30 && m < SUNRISE + 75 ? 'dawn' : m >= SUNSET - 75 && m < SUNSET + 35 ? 'dusk' : m >= SUNRISE && m < SUNSET ? 'day' : 'night'; }
362	function setTime(key) { offset = 0; if (key !== 'live') { const cur = minutes(new Date()), d = new Date(); offset = (TIME[key] - cur) * 60000 - d.getSeconds() * 1000 + 7000; } }
363	
364	let lastMin = -1;
365	function tick() {
366	  const d = now(), [h, m, s] = fTime.format(d).split(':');
367	  set('[data-hm]', `${h}:${m}`); set('[data-ss]', s);
368	  const mm = +h * 60 + +m;
369	  if (mm !== lastMin) { lastMin = mm; set('[data-date]', fDate.format(d)); renderWeather(); }
370	}
371	
372	/* ===== Vẽ số liệu ===== */
373	function renderWeather() {
374	  const m = minutes(now()), phase = phaseOf(m), nightIco = m < SUNRISE || m >= SUNSET, w = WX[S.wx], off = S.data === 'offline';
375	  env.dataset.phase = phase; env.dataset.state = S.data; env.dataset.concept = S.c;
376	  $$('[data-ico]').forEach((e) => { e.innerHTML = off ? '<path d="M7 18h10a4 4 0 0 0 .6-7.96A5.5 5.5 0 0 0 7.1 9.2 4.4 4.4 0 0 0 7 18z" opacity=".5"/><path d="M5 4l14 16"/>' : ICO[w.ico + (nightIco ? '-n' : '-d')]; });
377	  const desc = nightIco ? w.descNight : w.desc;
378	  set('[data-temp]', off ? '– –' : `${w.temp}°`); set('[data-temp-n]', off ? '– –' : w.temp);
379	  set('[data-desc]', off ? 'Chưa có số liệu' : desc); set('[data-desc-short]', off ? 'Mất kết nối' : desc);
380	  set('[data-feels]', off ? 'Đồng hồ vẫn chạy đúng giờ' : `Cảm giác như ${w.feels}°`);
381	  const dash = '—';
382	  $$('[data-hum]').forEach((e) => { e.innerHTML = off ? dash : `${w.hum}<small>%</small>`; });
383	  $$('[data-wind]').forEach((e) => { e.innerHTML = off ? dash : `${w.wind}<small>km/h</small>`; });
384	  $$('[data-rain]').forEach((e) => { e.innerHTML = off ? dash : `${vi(w.rain, 1)}<small>mm</small>`; });
385	  $$('[data-dir]').forEach((e) => { e.innerHTML = off ? dash : `<svg class="arrow env-ico" viewBox="0 0 12 12" style="transform:rotate(${w.dir + 180}deg)"><path d="M6 1.5v9M2.8 4.7L6 1.5l3.2 3.2"/></svg>${DIRS[Math.round(w.dir / 45) % 8]}`; });   // mũi tên chỉ hướng gió thổi tới
386	  $$('[data-cloud]').forEach((e) => { e.innerHTML = off ? dash : `${w.cloud}<small>%</small>`; });
387	  $$('[data-uv]').forEach((e) => { e.innerHTML = off ? dash : (nightIco ? 0 : w.uv) + (UV(nightIco ? 0 : w.uv) ? `<small>${UV(nightIco ? 0 : w.uv)}</small>` : ''); });
388	  // Vạch mặt trời
389	  const dot = document.getElementById('sunDot'), day = m >= SUNRISE && m < SUNSET;
390	  dot.style.left = `${Math.max(0, Math.min(1, (m - SUNRISE) / (SUNSET - SUNRISE))) * 100}%`; dot.style.opacity = day ? 1 : 0;
391	  const left = day ? SUNSET - m : (SUNRISE - m + 1440) % 1440, hh = Math.floor(left / 60), mi = left % 60;
392	  set('[data-sunnote]', `${day ? 'còn' : 'mọc sau'} ${hh ? hh + ' giờ ' : ''}${mi} phút${day ? ' nắng' : ''}`);
393	  // Chân thẻ: giờ quan trắc (số liệu Open-Meteo theo bước 15 phút)
394	  const obs = Math.floor(m / 15) * 15, foot = env.querySelector('[data-foot]');
