  const clear = () => { if (timer !== null) { d.clearTimer(timer); timer = null; } };
  const arm = (ms: number) => {
    clear();
    nextAt = d.now() + ms;
    if (visible && started) timer = d.setTimer(() => { timer = null; void refresh(); }, ms);
