import { chromium } from 'playwright';
import { readFileSync, mkdirSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
const WT = 'D:/2026 - Tuan/danang-vite/.worktrees/thoi-tiet-thuc';
const { serveDir } = await import(pathToFileURL(WT + '/tests/lib.mjs').href);
const OUT = process.argv[2];
const only = process.argv[3] || '';
mkdirSync(OUT, { recursive: true });
const FIX = JSON.parse(readFileSync(WT + '/tests/env-unit/fixture.json', 'utf8'));
// giờ quan trắc = giờ Đà Nẵng hiện tại làm tròn 15 phút
const ict = new Date(Date.now() + 7 * 3600e3);
const mm = Math.floor(ict.getUTCMinutes() / 15) * 15;
FIX.current.time = ict.toISOString().slice(0, 11) + String(ict.getUTCHours()).padStart(2, '0') + ':' + String(mm).padStart(2, '0');
const srv = await serveDir(WT + '/dist');
const browser = await chromium.launch({ headless: true, args: ['--use-angle=d3d11', '--ignore-gpu-blocklist', '--enable-gpu'] });
async function open(q, vp, mobile) {
  const ctx = await browser.newContext(mobile ? { viewport: vp, isMobile: true, hasTouch: true, deviceScaleFactor: 2 } : { viewport: vp });
  const page = await ctx.newPage();
  page.on('pageerror', (e) => console.log('pageerror', String(e)));
  page.on('console', (m) => { if (m.type() === 'error') console.log('console', m.text()); });
  await page.route(/googletagmanager|google-analytics|workers\.dev/, (r) => r.abort());
  let hits = 0;
  await page.route('**/api.open-meteo.com/**', (r) => { hits++; r.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify(FIX) }); });
  await page.goto(srv.url + q, { waitUntil: 'load', timeout: 180000 });
  await page.waitForFunction(() => window.__app && document.getElementById('loading')?.classList.contains('done'), null, { timeout: 180000 });
  await page.waitForTimeout(1500);
  console.log(q, 'open-meteo hits', hits);
  return { page, ctx };
}
const shot = async (page, name) => { await page.waitForTimeout(700); await page.screenshot({ path: OUT + '/' + name + '.png' }); console.log('shot', name); };
// ép giờ + số liệu khớp prototype
const force = (page, hh, mi, extra) => page.evaluate(({ hh, mi, extra }) => {
  const e = window.__app.env, t = Date.UTC(2026, 10, 14, hh - 7, mi);
  e.setNow(() => t);
  e.store.inject({ ...e.store.data, obs: t - 5 * 60000, obsMin: hh * 60 + mi - 5, ...extra });
}, { hh, mi, extra });

if (!only || only === 'desk') {
  const { page, ctx } = await open('?test&env=live', { width: 1440, height: 900 });
  await shot(page, 'desk-closed');
  await page.click('#envPill'); await shot(page, 'desk-open');
  await force(page, 13, 20, { temp: 29, feels: 33, hum: 68, wind: 14, dir: 45, rain: 0, cloud: 18, uv: 8, code: 1 });
  await shot(page, 'desk-open-1320');
  await page.click('#envPill'); await page.mouse.move(5, 500); await shot(page, 'desk-closed-1320');
  await page.hover('#envPill'); await shot(page, 'desk-hover-1320');
  await force(page, 21, 10, { temp: 25, feels: 27, hum: 84, wind: 9, dir: 220, rain: 0, cloud: 8, uv: 0, code: 0 });
  await page.click('#envPill'); await shot(page, 'desk-open-2110');
  await page.evaluate(() => window.__app.env.store.inject(null, true)); await shot(page, 'desk-open-offline');
  await page.evaluate(() => window.__app.env.store.inject(null, false)); await shot(page, 'desk-open-loading');
  await page.evaluate(() => { document.getElementById('langSelect').value = 'ar'; document.getElementById('langSelect').dispatchEvent(new Event('change')); });
  await force(page, 13, 20, { temp: 29, feels: 33, hum: 68, wind: 14, dir: 45, rain: 1.4, cloud: 18, uv: 8, code: 1 });
  await page.evaluate(() => window.__app.ui.openSheet('env')); await shot(page, 'desk-open-ar');
  await page.evaluate(() => window.__app.ui.openSheet('settings')); await shot(page, 'desk-settings-ar');
  await ctx.close();
}
if (!only || only === 'phone') {
  const { page, ctx } = await open('?test&env=live', { width: 390, height: 844 }, true);
  await force(page, 13, 20, { temp: 29, feels: 33, hum: 68, wind: 14, dir: 45, rain: 0, cloud: 18, uv: 8, code: 1 });
  await shot(page, 'phone-closed');
  await page.tap('#envPill'); await shot(page, 'phone-open');
  await force(page, 21, 10, { temp: 25, feels: 27, hum: 84, wind: 9, dir: 220, rain: 0, cloud: 8, uv: 0, code: 0 });
  await shot(page, 'phone-open-2110');
  await page.tap('#envScrim', { position: { x: 200, y: 100 } }); await shot(page, 'phone-closed-after-scrim');
  await ctx.close();
}
if (!only || only === 'explore') {
  for (const m of ['stroll', 'drive', 'bike', 'glider']) {
    const { page, ctx } = await open('?test&env=live&explore=' + m, { width: 1280, height: 720 });
    await page.waitForTimeout(1500);
